package com.example.todo.security; import jakarta.servlet.*; import jakarta.servlet.http.*; import lombok.RequiredArgsConstructor; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.web.authentication.WebAuthenticationDetailsSource; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.*; @Component @RequiredArgsConstructor public class JwtAuthenticationFilter extends OncePerRequestFilter {private final JwtService jwt;private final CustomUserDetailsService users; protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain f)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){String t=h.substring(7);if(jwt.valid(t)&&SecurityContextHolder.getContext().getAuthentication()==null){var d=users.loadUserByUsername(jwt.username(t));var a=new UsernamePasswordAuthenticationToken(d,null,d.getAuthorities());a.setDetails(new WebAuthenticationDetailsSource().buildDetails(r));SecurityContextHolder.getContext().setAuthentication(a);}}f.doFilter(r,s);}}
